// Independent central time-jet check of the native second-time oracle.
template<class T>std::vector<T*> entries(h::Z4cJet<T>&);
double SecondTimeVariation(const h::Z4cJet<AD>&u,const h::OmegaJet<AD>&o,h::Z4cJet<AD>timed,h::OmegaJet<AD>ot,double k1,double k2,int gaugeMode){
 timed.alpha.value.d[0]=gaugeMode?.013:0;double bv[3]={gaugeMode?.011:0,gaugeMode?-.007:0,gaugeMode?.005:0};for(int i=0;i<3;++i)timed.beta.value[i].d[0]=bv[i];h::SetStationaryOmegaNormal(timed.alpha.value,timed.beta.value,timed.alpha.d,timed.beta.d,ot);h::Z4cRHS<AD>ft{};if(!h::AssembleInterior(h::ConformalRHS(timed,ot,AD(k1),AD(k2)),ot.omega,ft))throw std::runtime_error("invalid AD oracle");AD zt[3]{};NativeZupVelocity(timed,ot,ft,zt);double err=0;
 for(double eps:{2.5e-6,1.25e-6,6.25e-7}){h::Z4cJet<AD>plus=u,minus=u,velocity=timed;auto pp=entries(plus),mp=entries(minus),vp=entries(velocity);for(unsigned i=0;i<pp.size();++i){*pp[i]=AD(pp[i]->v+eps*vp[i]->d[0]);*mp[i]=AD(mp[i]->v-eps*vp[i]->d[0]);}h::OmegaJet<AD>op{},om{};op.omega=om.omega=AD(o.omega.v);for(int i=0;i<3;++i){op.gradient[i]=om.gradient[i]=AD(o.gradient[i].v);for(int j=0;j<3;++j)op.hessian[i][j]=om.hessian[i][j]=AD(o.hessian[i][j].v);}h::SetStationaryOmegaNormal(plus.alpha.value,plus.beta.value,plus.alpha.d,plus.beta.d,op);h::SetStationaryOmegaNormal(minus.alpha.value,minus.beta.value,minus.alpha.d,minus.beta.d,om);h::Z4cRHS<AD>fp{},fm{};if(!h::AssembleInterior(h::ConformalRHS(plus,op,AD(k1),AD(k2)),op.omega,fp)||!h::AssembleInterior(h::ConformalRHS(minus,om,AD(k1),AD(k2)),om.omega,fm))throw std::runtime_error("invalid FD time jet");AD zp[3]{},zm[3]{};NativeZupVelocity(plus,op,fp,zp);NativeZupVelocity(minus,om,fm,zm);err=std::max(err,std::abs((fp.theta.v-fm.theta.v)/(2*eps)-ft.theta.d[0])/std::max(1.,std::abs(ft.theta.d[0])));for(int i=0;i<3;++i)err=std::max(err,std::abs((zp[i].v-zm[i].v)/(2*eps)-zt[i].d[0])/std::max(1.,std::abs(zt[i].d[0])));}
 return err;
}
